using HfDrive.Desktop.Services;
using HfDrive.Desktop.ViewModels;
using Microsoft.UI.Xaml;

namespace HfDrive.Desktop;

/// <summary>
/// WinUI application entry point (the entry point itself is generated by the
/// WinUI XAML compiler for WinExe projects). Owns the single provider session,
/// the root view model, the main window, the tray panel and the native
/// notification icon. The session is disposed only when this UI process exits:
/// closing the main window hides it to the tray and keeps the shared provider
/// session alive, because the desktop never owns provider lifetime.
///
/// Two distinct exits exist and are never conflated:
///   <c>Exit HF Drive</c> (this UI) disposes the icon, the panel and the IPC
///   session but leaves the provider running;
///   <c>Exit provider…</c> is a separately confirmed action that sends the
///   provider's own exit-provider command over IPC.
/// </summary>
public partial class App : Application
{
    private MainWindow? _window;
    private TrayWindow? _trayWindow;
    private TrayViewModel? _trayViewModel;
    private TrayService? _tray;
    private bool _exiting;
    private bool _uiTornDown;

    public App()
    {
        InitializeComponent();
        ViewModel = new MainViewModel(Session);
    }

    /// <summary>The one provider session shared by all views of this window.</summary>
    public ProviderSession Session { get; } = new();

    /// <summary>The root view model shared by all views of this window.</summary>
    public MainViewModel ViewModel { get; }

    /// <summary>
    /// The one application window, exposed so native pickers and other
    /// ownership surfaces can use its handle (native folder picker ownership).
    /// </summary>
    public Window? DesktopWindow => _window;

    /// <summary>The tray panel window (hidden until the tray icon is used).</summary>
    public TrayWindow? TrayPanel => _trayWindow;

    protected override void OnLaunched(LaunchActivatedEventArgs args)
    {
        ViewModel.ApplySessionState();
        _window = new MainWindow(ViewModel);
        _window.Closed += OnMainWindowClosed;
        _window.Title = "HF Drive";

        // Close-to-tray: the AppWindow.Closing event lets us cancel the close
        // and hide instead. MainWindow's own teardown runs only on a real
        // process exit (ExitUi), never on a hide.
        _window.AppWindow.Closing += OnMainWindowClosing;

        // Activate the main window first so its real HWND exists before the
        // tray icon subclasses it.
        _window.Activate();

        // The tray panel and icon share the same provider session and view
        // state; they are created once and survive every hide/show cycle.
        _trayViewModel = new TrayViewModel(Session);
        _trayWindow = new TrayWindow(_trayViewModel);
        _tray = new TrayService(_window);
        _trayWindow.AttachTray(_tray);

        // The tray window's hidden HWND initialization can steal activation
        // from the main window; restore foreground to the onboarding surface.
        _window.Activate();
    }

    /// <summary>Reopens the current surface without navigating away from unfinished setup.</summary>
    public void OpenMainWindow()
    {
        if (_window is not { } window) return;
        window.AppWindow.Show();
        window.Activate();
    }

    /// <summary>
    /// Shows and activates the main window at one of the contracted sections
    /// (account, connections, operations, setup). Preserves an unfinished
    /// onboarding flow exactly as <c>MainWindow.OpenSection</c> defines it.
    /// </summary>
    public void OpenMainSection(string tag) => OpenMainSection(tag, null, null);

    /// <summary>
    /// Section navigation scoped to one connection and, for the operations
    /// surface, one recorded conflict to load and select for explicit user
    /// resolution. Never resolves or mutates anything on its own.
    /// </summary>
    public void OpenMainSection(string tag, Guid? connectionId, Guid? conflictId)
    {
        _window?.OpenSection(tag, connectionId, conflictId);
    }

    // ── Close-to-tray and exit paths ─────────────────────────────────────

    private void OnMainWindowClosing(object sender, Microsoft.UI.Windowing.AppWindowClosingEventArgs e)
    {
        // A close from the title bar hides to the tray; the provider session,
        // tray icon and panel keep running so hydration and status continue.
        if (_exiting) return;
        e.Cancel = true;
        _window?.AppWindow.Hide();
    }

    private void OnMainWindowClosed(object sender, WindowEventArgs args) => TeardownUi();

    /// <summary>Releases every UI-owned resource exactly once. The provider is
    /// never stopped here; only this UI's IPC session ends.</summary>
    private void TeardownUi()
    {
        if (_uiTornDown) return;
        _uiTornDown = true;
        _trayWindow?.DisposePanel();
        _tray?.Dispose();
        _trayWindow = null;
        _trayViewModel?.Dispose();
        _trayViewModel = null;
        ViewModel.Dispose();
    }

    /// <summary>
    /// "Exit HF Drive": closes only this UI process (icon, panel and IPC
    /// session), leaving the provider running. Never stops the provider. The
    /// process ends after the session closes, deterministically, regardless of
    /// whether any window is open.
    /// </summary>
    public void ExitUi()
    {
        if (_exiting) return;
        _exiting = true;
        TeardownUi();
        _ = ExitProcessWhenSessionClosedAsync();
    }

    private async Task ExitProcessWhenSessionClosedAsync()
    {
        try
        {
            await Session.DisposeAsync().ConfigureAwait(false);
        }
        catch (Exception)
        {
            // Never let a session teardown failure strand the process.
        }
        Environment.Exit(0);
    }

    /// <summary>
    /// "Exit provider…": the separately confirmed destructive action. Sends the
    /// provider's own exit-provider command over IPC (real mutation, real
    /// operation UUID) and then exits this UI as well.
    /// </summary>
    public async Task ExitProviderAsync()
    {
        if (_exiting) return;
        try
        {
            await Session.SendAsync(Protocol.Commands.ExitProvider, new Protocol.ExitProviderRequest
            {
                OperationId = Guid.NewGuid(),
            }, CancellationToken.None).ConfigureAwait(true);
        }
        catch (Exception)
        {
            // A refused/unavailable exit is reported by the provider surface;
            // never pretend the provider stopped.
        }
        ExitUi();
    }
}
